insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f0beb02a-61cb-4dd1-8658-5db953b8a723', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Vector Mechanics Review and Modeling Workflow', 'This opening unit prepares students to translate physical motion into solvable engineering models. It keeps the course grounded in diagrams, units, coordinates, and assumptions before equations appear.', 0),
  ('38281cd4-27b6-4b0e-96fb-48ddbfc6a790', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f0beb02a-61cb-4dd1-8658-5db953b8a723', 'subtopic'::public.curated_course_node_type, 'Vectors and components', 'Students review how to represent motion, force, and moment quantities in component form. The point is to make geometry computationally reliable.', 0),
  ('fa006294-b9dc-4a77-b7a9-64cdd6960fb7', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '38281cd4-27b6-4b0e-96fb-48ddbfc6a790', 'concept'::public.curated_course_node_type, 'Unit vectors', null, 0),
  ('02a7bc19-f611-4453-a363-506ef73fbcac', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '38281cd4-27b6-4b0e-96fb-48ddbfc6a790', 'concept'::public.curated_course_node_type, 'Cartesian components', null, 1),
  ('444e78d0-ee7e-454c-8feb-e24384b3d314', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '38281cd4-27b6-4b0e-96fb-48ddbfc6a790', 'concept'::public.curated_course_node_type, 'Magnitude and direction', null, 2),
  ('bd460999-8aca-4b34-bc3d-3d293120cc6a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '38281cd4-27b6-4b0e-96fb-48ddbfc6a790', 'concept'::public.curated_course_node_type, 'Dot and cross products', null, 3),
  ('0bed45f0-0417-463b-8b48-34f7ade943b5', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f0beb02a-61cb-4dd1-8658-5db953b8a723', 'subtopic'::public.curated_course_node_type, 'Free-body and kinetic diagrams', 'Dynamics problems require both the forces on a body and the motion response. Students learn to pair free-body diagrams with acceleration or kinetic diagrams.', 1),
  ('76efb8c6-5d73-4af0-8269-fd7d708e00ea', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0bed45f0-0417-463b-8b48-34f7ade943b5', 'concept'::public.curated_course_node_type, 'Isolating the body', null, 0),
  ('8d1dab65-f2a4-4e22-82d4-e8ed6f7e70ef', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0bed45f0-0417-463b-8b48-34f7ade943b5', 'concept'::public.curated_course_node_type, 'Forces and moments', null, 1),
  ('ca6d51fb-9341-4dd2-b8ed-7b9c804bc9a0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0bed45f0-0417-463b-8b48-34f7ade943b5', 'concept'::public.curated_course_node_type, 'Mass times acceleration diagrams', null, 2),
  ('62b20901-cbd5-4e72-ad59-4fb7034e0788', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0bed45f0-0417-463b-8b48-34f7ade943b5', 'concept'::public.curated_course_node_type, 'Sign conventions', null, 3),
  ('675cded4-b1a5-4dca-95ba-26d54daf87a2', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f0beb02a-61cb-4dd1-8658-5db953b8a723', 'subtopic'::public.curated_course_node_type, 'Modeling assumptions', 'Students learn to simplify without hiding the physics. The gist is to state what is ignored and why the model remains useful.', 2),
  ('01dfdae7-9250-4408-b9ce-9ba00bd3501a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '675cded4-b1a5-4dca-95ba-26d54daf87a2', 'concept'::public.curated_course_node_type, 'Particle versus rigid body', null, 0),
  ('831c0114-f346-4802-b3a7-097d168fbc9c', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '675cded4-b1a5-4dca-95ba-26d54daf87a2', 'concept'::public.curated_course_node_type, 'Neglecting friction or air resistance', null, 1),
  ('9d7b7c44-9384-4ee7-8a7f-869ef7318dca', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '675cded4-b1a5-4dca-95ba-26d54daf87a2', 'concept'::public.curated_course_node_type, 'Ideal cables and pulleys', null, 2),
  ('9f46886c-67b7-4090-b5d2-405d376a53cc', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '675cded4-b1a5-4dca-95ba-26d54daf87a2', 'concept'::public.curated_course_node_type, 'Planar versus spatial motion', null, 3),
  ('82df833b-a47f-494e-89d5-51961595501b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f0beb02a-61cb-4dd1-8658-5db953b8a723', 'subtopic'::public.curated_course_node_type, 'Problem-solving workflow', 'Students learn a repeatable method for dynamics problems. This reduces algebra drift and helps catch impossible answers.', 3),
  ('56fef95a-62bc-476f-abfd-5a0573c06db5', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '82df833b-a47f-494e-89d5-51961595501b', 'concept'::public.curated_course_node_type, 'Knowns and unknowns', null, 0),
  ('e75855f2-7e61-4f57-9384-7a351eb82131', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '82df833b-a47f-494e-89d5-51961595501b', 'concept'::public.curated_course_node_type, 'Coordinate choice', null, 1),
  ('09cb61f7-6652-449a-9bab-7a5bc7ea8cc1', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '82df833b-a47f-494e-89d5-51961595501b', 'concept'::public.curated_course_node_type, 'Equation selection', null, 2),
  ('78fcce83-e9d5-4d7c-b0bc-397d2afcb3a7', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '82df833b-a47f-494e-89d5-51961595501b', 'concept'::public.curated_course_node_type, 'Units and reasonableness checks', null, 3),
  ('ddd1dc5b-7ef3-4a73-88b7-16b8b1fc8fac', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Particle Kinematics: Rectilinear and Curvilinear Motion', 'This unit studies motion without yet asking what caused it. Students learn to describe position, velocity, and acceleration accurately in one, two, and three dimensions.', 1),
  ('6d8cc0b7-b3ae-4ff8-a04c-0b21ef10f25b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ddd1dc5b-7ef3-4a73-88b7-16b8b1fc8fac', 'subtopic'::public.curated_course_node_type, 'Rectilinear motion', 'Students learn motion along a straight line. The gist is to connect displacement, velocity, and acceleration through calculus and graphs.', 0),
  ('94f14cfb-25fe-4bf0-a818-2c2aee130a31', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d8cc0b7-b3ae-4ff8-a04c-0b21ef10f25b', 'concept'::public.curated_course_node_type, 'Position-time functions', null, 0),
  ('71b9b655-1f01-46df-81a1-1eb6318e0888', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d8cc0b7-b3ae-4ff8-a04c-0b21ef10f25b', 'concept'::public.curated_course_node_type, 'Velocity as derivative', null, 1),
  ('06fcd68a-df54-449d-9962-cce05c393682', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d8cc0b7-b3ae-4ff8-a04c-0b21ef10f25b', 'concept'::public.curated_course_node_type, 'Acceleration as derivative', null, 2),
  ('edeca0c5-c85d-45dd-8347-b08bdf71edec', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d8cc0b7-b3ae-4ff8-a04c-0b21ef10f25b', 'concept'::public.curated_course_node_type, 'Constant-acceleration equations', null, 3),
  ('6d2aba88-e691-4d0c-8e84-533fcbaed79d', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ddd1dc5b-7ef3-4a73-88b7-16b8b1fc8fac', 'subtopic'::public.curated_course_node_type, 'Curvilinear motion', 'Students learn how motion along a curved path differs from straight-line motion. Acceleration can exist even at constant speed because direction changes.', 1),
  ('a5eb801d-dc59-4bd2-98fd-e06e9ffe9109', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d2aba88-e691-4d0c-8e84-533fcbaed79d', 'concept'::public.curated_course_node_type, 'Vector position', null, 0),
  ('d876c84a-7703-4303-8669-4477dbc6db3b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d2aba88-e691-4d0c-8e84-533fcbaed79d', 'concept'::public.curated_course_node_type, 'Velocity tangent to path', null, 1),
  ('241caf7a-61a7-4469-9346-23b34f73de24', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d2aba88-e691-4d0c-8e84-533fcbaed79d', 'concept'::public.curated_course_node_type, 'Normal acceleration', null, 2),
  ('f008983e-cc51-4ace-981c-d48589dc7eed', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6d2aba88-e691-4d0c-8e84-533fcbaed79d', 'concept'::public.curated_course_node_type, 'Tangential acceleration', null, 3),
  ('bb44dd84-13a2-45b0-bd97-7a12d80dc343', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ddd1dc5b-7ef3-4a73-88b7-16b8b1fc8fac', 'subtopic'::public.curated_course_node_type, 'Motion graphs', 'Graphs reveal relationships that equations can hide. Students learn to interpret slopes and areas physically.', 2),
  ('20cf0534-d4cf-4425-8dc3-2d109f3b0e07', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'bb44dd84-13a2-45b0-bd97-7a12d80dc343', 'concept'::public.curated_course_node_type, 'x-t, v-t, and a-t graphs', null, 0),
  ('487b6c05-d73c-4f84-846e-dc265cc809fe', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'bb44dd84-13a2-45b0-bd97-7a12d80dc343', 'concept'::public.curated_course_node_type, 'Area under velocity', null, 1),
  ('8942ce9c-8502-49a5-8181-f77e00c287ef', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'bb44dd84-13a2-45b0-bd97-7a12d80dc343', 'concept'::public.curated_course_node_type, 'Area under acceleration', null, 2),
  ('3b77716f-5bda-4449-9e27-5feb9fb8804c', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'bb44dd84-13a2-45b0-bd97-7a12d80dc343', 'concept'::public.curated_course_node_type, 'Piecewise motion', null, 3),
  ('b3ff1fb4-2cbb-470a-a2d8-a49e6deb65a5', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ddd1dc5b-7ef3-4a73-88b7-16b8b1fc8fac', 'subtopic'::public.curated_course_node_type, 'Projectile and path motion', 'Students apply kinematics to common engineering examples. The point is to practice decomposition into independent directions.', 3),
  ('a8206a86-9e3c-4a52-90ca-109ae59bc332', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b3ff1fb4-2cbb-470a-a2d8-a49e6deb65a5', 'concept'::public.curated_course_node_type, 'Projectile motion', null, 0),
  ('a7e79501-8bcc-4b97-a97d-ec6aee79f622', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b3ff1fb4-2cbb-470a-a2d8-a49e6deb65a5', 'concept'::public.curated_course_node_type, 'Trajectory equations', null, 1),
  ('c9ce7f98-293a-423c-a918-8d27d5101eee', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b3ff1fb4-2cbb-470a-a2d8-a49e6deb65a5', 'concept'::public.curated_course_node_type, 'Range and time of flight', null, 2),
  ('cb0555e5-c752-4b62-920c-31450b5ae1d8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b3ff1fb4-2cbb-470a-a2d8-a49e6deb65a5', 'concept'::public.curated_course_node_type, 'Path constraints', null, 3),
  ('b75f3234-070c-4339-944c-597cf2716c7d', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Coordinate Systems and Relative Motion of Particles', 'This unit teaches students to choose coordinates that fit the motion. Good coordinate choices make hard problems much cleaner.', 2),
  ('be9e6965-5813-4852-be51-6e2bef80fd11', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b75f3234-070c-4339-944c-597cf2716c7d', 'subtopic'::public.curated_course_node_type, 'Normal-tangential coordinates', 'Students learn to describe motion along a known path. This is especially useful for vehicles, cams, and curved guides.', 0),
  ('3d8ae921-a001-4554-b393-b72520082f93', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'be9e6965-5813-4852-be51-6e2bef80fd11', 'concept'::public.curated_course_node_type, 'Tangential acceleration', null, 0),
  ('afd3a5f1-9fdf-4211-9592-02e67d25f4d3', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'be9e6965-5813-4852-be51-6e2bef80fd11', 'concept'::public.curated_course_node_type, 'Normal acceleration', null, 1),
  ('480df945-509f-4525-ac2c-fcd95f7062fd', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'be9e6965-5813-4852-be51-6e2bef80fd11', 'concept'::public.curated_course_node_type, 'Radius of curvature', null, 2),
  ('7b4dfeae-bbea-4ea2-b144-c5e6f38cf7db', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'be9e6965-5813-4852-be51-6e2bef80fd11', 'concept'::public.curated_course_node_type, 'Speed along a path', null, 3),
  ('c1aec90a-bf3e-4e7c-a835-e82394a00628', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b75f3234-070c-4339-944c-597cf2716c7d', 'subtopic'::public.curated_course_node_type, 'Polar and cylindrical coordinates', 'Students learn motion described by radial and angular variables. The gist is that unit vectors can change direction over time.', 1),
  ('5ccab343-c968-4a47-88e2-c6f6058508b5', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c1aec90a-bf3e-4e7c-a835-e82394a00628', 'concept'::public.curated_course_node_type, 'Radial velocity and acceleration', null, 0),
  ('c1294c99-e3c4-4d3e-9d3f-e765a6b70979', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c1aec90a-bf3e-4e7c-a835-e82394a00628', 'concept'::public.curated_course_node_type, 'Transverse velocity and acceleration', null, 1),
  ('d3142b80-e4ba-40bc-9ce1-ee34666bb0c0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c1aec90a-bf3e-4e7c-a835-e82394a00628', 'concept'::public.curated_course_node_type, 'Angular velocity', null, 2),
  ('65f7d3d0-5d41-43e7-8e64-647c3115563c', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c1aec90a-bf3e-4e7c-a835-e82394a00628', 'concept'::public.curated_course_node_type, 'Cylindrical extension', null, 3),
  ('f6537363-9764-4ce1-8687-73ad1eecf532', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b75f3234-070c-4339-944c-597cf2716c7d', 'subtopic'::public.curated_course_node_type, 'Relative motion', 'Students learn to describe one particle''s motion as observed from another. This supports pursuit, linkages, and moving-frame problems.', 2),
  ('49e2806a-6bc3-4f05-a86d-3847744f94dc', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f6537363-9764-4ce1-8687-73ad1eecf532', 'concept'::public.curated_course_node_type, 'Relative position', null, 0),
  ('47f27d0b-a7c2-43fe-a1d3-0ce2f025fc29', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f6537363-9764-4ce1-8687-73ad1eecf532', 'concept'::public.curated_course_node_type, 'Relative velocity', null, 1),
  ('f3db5e23-b7d2-4ca1-a72b-ce98021261b8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f6537363-9764-4ce1-8687-73ad1eecf532', 'concept'::public.curated_course_node_type, 'Relative acceleration', null, 2),
  ('69375682-de25-4ba7-bb2a-fae37b809392', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f6537363-9764-4ce1-8687-73ad1eecf532', 'concept'::public.curated_course_node_type, 'Dependent motion', null, 3),
  ('85edda0a-eb51-42ea-a305-d756208a89d0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'b75f3234-070c-4339-944c-597cf2716c7d', 'subtopic'::public.curated_course_node_type, 'Constrained motion', 'Students practice motion relationships created by cables, pulleys, sliders, and mechanisms.', 3),
  ('6d235882-be15-4123-8d41-7dae1910000f', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '85edda0a-eb51-42ea-a305-d756208a89d0', 'concept'::public.curated_course_node_type, 'Cable-length constraints', null, 0),
  ('8cc1e36b-ada4-44c9-850a-85b43a0927f3', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '85edda0a-eb51-42ea-a305-d756208a89d0', 'concept'::public.curated_course_node_type, 'Pulley systems', null, 1),
  ('d7720871-316d-4330-8cbb-0e2a2efc3e5b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '85edda0a-eb51-42ea-a305-d756208a89d0', 'concept'::public.curated_course_node_type, 'Linked coordinates', null, 2),
  ('68790abe-48b7-4bd2-8a8c-d3b75a04d9e9', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '85edda0a-eb51-42ea-a305-d756208a89d0', 'concept'::public.curated_course_node_type, 'Differentiating constraints', null, 3),
  ('f1b85dd4-c19b-4606-8db4-48e1ce64d1f2', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Particle Kinetics Using Newton''s Laws', 'This unit introduces force as the cause of acceleration. Students learn to connect free-body diagrams directly to equations of motion.', 3),
  ('5afbb4e9-2c2d-4a40-ae7d-431e8918caf6', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f1b85dd4-c19b-4606-8db4-48e1ce64d1f2', 'subtopic'::public.curated_course_node_type, 'Newton''s second law', 'Students use F = ma as the core force-acceleration relationship. The point is to write equations in directions aligned with the motion.', 0),
  ('d0bdb26b-6b4e-4630-9597-8dc19be2e890', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5afbb4e9-2c2d-4a40-ae7d-431e8918caf6', 'concept'::public.curated_course_node_type, 'Inertial frames', null, 0),
  ('adb68a33-684c-471c-a2cb-53e3e89f4ee7', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5afbb4e9-2c2d-4a40-ae7d-431e8918caf6', 'concept'::public.curated_course_node_type, 'Component equations', null, 1),
  ('888500a2-3a14-4d60-98f3-f716c2ddbdfa', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5afbb4e9-2c2d-4a40-ae7d-431e8918caf6', 'concept'::public.curated_course_node_type, 'Mass and weight', null, 2),
  ('32669edb-60ed-4ff4-ade9-47cf678b0496', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5afbb4e9-2c2d-4a40-ae7d-431e8918caf6', 'concept'::public.curated_course_node_type, 'Resultant force', null, 3),
  ('db73c846-8fee-4736-be02-674f1c727309', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f1b85dd4-c19b-4606-8db4-48e1ce64d1f2', 'subtopic'::public.curated_course_node_type, 'Rectangular and path-coordinate kinetics', 'Students learn that the same law can be written in different coordinate systems. The best choice depends on the motion.', 1),
  ('d8711dbb-7494-4966-9648-4d7c64f8d750', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'db73c846-8fee-4736-be02-674f1c727309', 'concept'::public.curated_course_node_type, 'Cartesian equations', null, 0),
  ('b918a5a0-1443-4dc2-986c-873806258db4', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'db73c846-8fee-4736-be02-674f1c727309', 'concept'::public.curated_course_node_type, 'Normal-tangential equations', null, 1),
  ('ed0a23d9-579b-4b9a-ad3c-da6ff7519797', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'db73c846-8fee-4736-be02-674f1c727309', 'concept'::public.curated_course_node_type, 'Polar equations', null, 2),
  ('2ae2bf3d-7d01-4723-a7ee-fe683fd228a2', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'db73c846-8fee-4736-be02-674f1c727309', 'concept'::public.curated_course_node_type, 'Radial and transverse force balance', null, 3),
  ('33c63928-bb26-4518-8db6-1edaa394996f', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f1b85dd4-c19b-4606-8db4-48e1ce64d1f2', 'subtopic'::public.curated_course_node_type, 'Friction and contact forces', 'Students include real interaction forces in motion problems. The gist is to distinguish normal reactions from resistance forces.', 2),
