  ('6fa0c1f8-541c-40af-ace7-bc31f1cd26b1', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '33c63928-bb26-4518-8db6-1edaa394996f', 'concept'::public.curated_course_node_type, 'Normal force', null, 1),
  ('b5e36ffe-e6c3-4aa6-a06c-1f49d7fbf5c0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '33c63928-bb26-4518-8db6-1edaa394996f', 'concept'::public.curated_course_node_type, 'Contact constraints', null, 2),
  ('101c281e-8ac7-47c9-9994-69fa59fef8c8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '33c63928-bb26-4518-8db6-1edaa394996f', 'concept'::public.curated_course_node_type, 'Rolling resistance overview', null, 3),
  ('3fe8b606-8a6b-4d52-b885-60e37373d913', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'f1b85dd4-c19b-4606-8db4-48e1ce64d1f2', 'subtopic'::public.curated_course_node_type, 'Applications', 'Students apply Newton''s laws to common systems. This builds fluency in setup, not just computation.', 3);
