  ('58a807a5-ae15-4408-a33d-6c314f52726a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '3fe8b606-8a6b-4d52-b885-60e37373d913', 'concept'::public.curated_course_node_type, 'Springs and dampers', null, 3),
  ('adb7b9af-ba7d-4039-845f-6ff7ca1b9aa7', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Work-Energy Methods for Particles', 'Work-energy methods offer an efficient alternative when displacement and speed matter more than time. Students learn to solve motion problems without always tracking acceleration histories.', 4),
  ('ed5e9222-885b-4858-bf5d-5806b717f897', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'adb7b9af-ba7d-4039-845f-6ff7ca1b9aa7', 'subtopic'::public.curated_course_node_type, 'Work of a force', 'Students learn how forces transfer energy through displacement. The gist is that only the component along motion does work.', 0),
  ('3486fb6e-98a1-4de4-a58e-862fa1368510', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ed5e9222-885b-4858-bf5d-5806b717f897', 'concept'::public.curated_course_node_type, 'Constant force work', null, 0),
  ('1af5b19c-ce68-4120-875b-569c0e84785a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ed5e9222-885b-4858-bf5d-5806b717f897', 'concept'::public.curated_course_node_type, 'Variable force work', null, 1),
  ('a022bdef-3809-4d01-bd4a-b04b5d325719', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ed5e9222-885b-4858-bf5d-5806b717f897', 'concept'::public.curated_course_node_type, 'Work from force-position graphs', null, 2),
  ('7f02ddd7-4109-4604-be34-175fbaad894a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ed5e9222-885b-4858-bf5d-5806b717f897', 'concept'::public.curated_course_node_type, 'Work by weight and springs', null, 3),
  ('09080319-fd51-4913-9b1d-6de0a0e4cd9a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'adb7b9af-ba7d-4039-845f-6ff7ca1b9aa7', 'subtopic'::public.curated_course_node_type, 'Kinetic energy', 'Students connect mass and speed to energy of motion.', 1),
  ('7f39935e-212f-46e3-8453-82ea55957e60', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '09080319-fd51-4913-9b1d-6de0a0e4cd9a', 'concept'::public.curated_course_node_type, 'Translational kinetic energy', null, 0),
  ('76ebdd87-c455-4518-a6d1-13f5452c88b0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '09080319-fd51-4913-9b1d-6de0a0e4cd9a', 'concept'::public.curated_course_node_type, 'Change in kinetic energy', null, 1),
  ('65145922-6f81-46f5-a605-dbd5c4215650', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '09080319-fd51-4913-9b1d-6de0a0e4cd9a', 'concept'::public.curated_course_node_type, 'Units of energy', null, 2),
  ('ed932f13-0084-4333-b941-5138a4ae1357', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '09080319-fd51-4913-9b1d-6de0a0e4cd9a', 'concept'::public.curated_course_node_type, 'Speed from energy balance', null, 3),
  ('02f77040-f0df-4d91-a68a-a03ecfc69f1a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'adb7b9af-ba7d-4039-845f-6ff7ca1b9aa7', 'subtopic'::public.curated_course_node_type, 'Principle of work and energy', 'Students learn a compact equation for relating initial and final states.', 2),
  ('b271e939-51c1-4e13-9248-8807797133f3', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '02f77040-f0df-4d91-a68a-a03ecfc69f1a', 'concept'::public.curated_course_node_type, 'Initial and final kinetic energy', null, 0),
  ('97514912-0688-42ff-b8e4-720a272af9b1', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '02f77040-f0df-4d91-a68a-a03ecfc69f1a', 'concept'::public.curated_course_node_type, 'Net work', null, 1),
  ('188a2465-7eef-4146-98c7-e936358d873b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '02f77040-f0df-4d91-a68a-a03ecfc69f1a', 'concept'::public.curated_course_node_type, 'Path-dependent forces', null, 2),
  ('bd7a1589-90de-4678-ad2b-2dd8b6d3a695', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '02f77040-f0df-4d91-a68a-a03ecfc69f1a', 'concept'::public.curated_course_node_type, 'State comparison', null, 3),
  ('e2c7906e-6cba-4592-b33a-db8d54be046f', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'adb7b9af-ba7d-4039-845f-6ff7ca1b9aa7', 'subtopic'::public.curated_course_node_type, 'Conservative forces and potential energy', 'Students learn when energy can be stored and recovered. This sets up conservation methods.', 3),
  ('f7ef6af7-e426-41e1-bc28-b734dbbff821', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'e2c7906e-6cba-4592-b33a-db8d54be046f', 'concept'::public.curated_course_node_type, 'Gravitational potential energy', null, 0),
