  ('b19e506e-eac5-4884-93e3-edd6d8cfbef6', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'e2c7906e-6cba-4592-b33a-db8d54be046f', 'concept'::public.curated_course_node_type, 'Conservation of mechanical energy', null, 2),
  ('26a8955c-d862-4934-a925-a834e1ab2b5c', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'e2c7906e-6cba-4592-b33a-db8d54be046f', 'concept'::public.curated_course_node_type, 'Nonconservative work', null, 3),
  ('3bd52d85-741a-48a0-8747-e357947fef5a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Impulse, Momentum, and Impact for Particles', 'Momentum methods are strongest when forces act over time, especially during collisions or short impulses. Students learn to analyze interactions where acceleration is hard to model directly.', 5),
  ('af03b373-0a63-42e9-a3a1-f83463a2be53', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '3bd52d85-741a-48a0-8747-e357947fef5a', 'subtopic'::public.curated_course_node_type, 'Linear impulse and momentum', 'Students learn the time-integral form of Newton''s second law. The point is to relate force duration to velocity change.', 0),
  ('c020e53a-9a95-4218-944a-353dd147acff', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'af03b373-0a63-42e9-a3a1-f83463a2be53', 'concept'::public.curated_course_node_type, 'Impulse', null, 0),
  ('bc00e7c0-0b28-46f9-9ec5-c5d2c86a6a7d', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'af03b373-0a63-42e9-a3a1-f83463a2be53', 'concept'::public.curated_course_node_type, 'Linear momentum', null, 1),
  ('7439a07c-3596-4dbf-892c-4143d0fb4488', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'af03b373-0a63-42e9-a3a1-f83463a2be53', 'concept'::public.curated_course_node_type, 'Impulse-momentum equation', null, 2),
  ('2280df5a-1b17-404d-a26b-40b412e1abb6', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'af03b373-0a63-42e9-a3a1-f83463a2be53', 'concept'::public.curated_course_node_type, 'Average impulsive force', null, 3),
  ('5283fe7c-56e5-49d0-b6ae-7052f079b60c', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '3bd52d85-741a-48a0-8747-e357947fef5a', 'subtopic'::public.curated_course_node_type, 'Conservation of momentum', 'Students learn when total momentum remains constant for a system. This is essential for collisions and explosions.', 1),
  ('44b941ed-f2b6-4e7d-a06c-8ab35698dceb', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5283fe7c-56e5-49d0-b6ae-7052f079b60c', 'concept'::public.curated_course_node_type, 'System boundaries', null, 0),
  ('dbac452b-4303-4058-86c5-ec88c02eb256', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5283fe7c-56e5-49d0-b6ae-7052f079b60c', 'concept'::public.curated_course_node_type, 'Internal versus external forces', null, 1),
  ('a7c70d97-cbfc-4a2b-8b84-98308d14f9a0', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5283fe7c-56e5-49d0-b6ae-7052f079b60c', 'concept'::public.curated_course_node_type, 'Momentum in components', null, 2),
  ('bdea1196-e283-4c13-a883-a18ced4db163', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5283fe7c-56e5-49d0-b6ae-7052f079b60c', 'concept'::public.curated_course_node_type, 'Explosions and recoil', null, 3),
  ('64b46a35-00bf-4598-b9ed-925e360952af', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '3bd52d85-741a-48a0-8747-e357947fef5a', 'subtopic'::public.curated_course_node_type, 'Impact', 'Students model collisions using momentum and restitution. The gist is to handle short-duration contact without detailed deformation analysis.', 2),
  ('70da18f5-1891-4a5e-a0c7-f09a3f746bd9', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '64b46a35-00bf-4598-b9ed-925e360952af', 'concept'::public.curated_course_node_type, 'Coefficient of restitution', null, 0),
  ('5b7f1a04-e25a-48ec-b434-4ec39b763e01', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '64b46a35-00bf-4598-b9ed-925e360952af', 'concept'::public.curated_course_node_type, 'Direct central impact', null, 1),
  ('cee856bb-f5d3-420d-913a-5d64609aa609', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '64b46a35-00bf-4598-b9ed-925e360952af', 'concept'::public.curated_course_node_type, 'Oblique impact', null, 2),
  ('e2d5b67d-fe56-45a5-8640-c7958123d6ad', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '64b46a35-00bf-4598-b9ed-925e360952af', 'concept'::public.curated_course_node_type, 'Energy loss in impact', null, 3),
