  ('45583899-de7c-470c-9711-ed8aab1bd3c9', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a9db0bde-9647-4417-b325-4375ccb83709', 'concept'::public.curated_course_node_type, 'Angular impulse', null, 1),
  ('546c3385-99af-4fec-b781-751768c868dd', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a9db0bde-9647-4417-b325-4375ccb83709', 'concept'::public.curated_course_node_type, 'Conservation about a fixed point', null, 2),
  ('6d0a9eba-f34c-4a9d-bd6c-5d490000a5cb', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a9db0bde-9647-4417-b325-4375ccb83709', 'concept'::public.curated_course_node_type, 'Central-force motion overview', null, 3),
