  ('f0421275-3b38-4af6-84d4-22c73a791ae8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '79b8ea4a-dbf4-45ac-b4b0-bde460569f33', 'concept'::public.curated_course_node_type, 'Continuous bodies', null, 1),
  ('d1bcb4aa-ef17-4623-8192-0cd31057fe24', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '79b8ea4a-dbf4-45ac-b4b0-bde460569f33', 'concept'::public.curated_course_node_type, 'Centroid versus center of mass', null, 2),
  ('eb077618-3912-467a-81bc-45d16ac249c8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '79b8ea4a-dbf4-45ac-b4b0-bde460569f33', 'concept'::public.curated_course_node_type, 'Composite systems', null, 3),
  ('6e32c535-a1eb-4614-b31b-b848c0086404', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ef31c5a5-bb9d-49e9-9f7e-c0e2df77a17c', 'subtopic'::public.curated_course_node_type, 'System linear momentum', 'Students extend momentum methods to multiple bodies. This supports vehicle, projectile, and collision systems.', 1),
  ('51457b04-18f5-4e65-84d4-7b559855c171', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6e32c535-a1eb-4614-b31b-b848c0086404', 'concept'::public.curated_course_node_type, 'Total momentum', null, 0),
  ('28257074-194c-4a44-be2a-0d00ebba82b3', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6e32c535-a1eb-4614-b31b-b848c0086404', 'concept'::public.curated_course_node_type, 'External impulse', null, 1),
  ('ebf48695-24fa-4d16-9de7-1fb41318715b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '6e32c535-a1eb-4614-b31b-b848c0086404', 'concept'::public.curated_course_node_type, 'Internal force cancellation', null, 2),
