  ('c0f9858e-0447-46ad-8c67-04687076652a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'ef31c5a5-bb9d-49e9-9f7e-c0e2df77a17c', 'subtopic'::public.curated_course_node_type, 'System work-energy', 'Students learn how energy methods apply to interacting particles.', 2),
