  ('1c8b592c-e5d3-4244-b541-d88fa3dfd604', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c0f9858e-0447-46ad-8c67-04687076652a', 'concept'::public.curated_course_node_type, 'Internal work', null, 1),
  ('f358fd81-b799-4d10-bb65-61e7022c9ba3', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'c0f9858e-0447-46ad-8c67-04687076652a', 'concept'::public.curated_course_node_type, 'External work', null, 2),
