  ('8f2bcbbb-47f9-4cec-8920-e4fb8fdfb13a', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a1061279-b3f3-42f1-929f-6d7424ec6950', 'concept'::public.curated_course_node_type, 'Coriolis acceleration', null, 0),
  ('243d66d5-c004-4f59-b3fe-52b926826c9f', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a1061279-b3f3-42f1-929f-6d7424ec6950', 'concept'::public.curated_course_node_type, 'Centripetal acceleration', null, 1),
  ('98ea0359-65a9-41a9-9929-bcab4a35c4bf', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a1061279-b3f3-42f1-929f-6d7424ec6950', 'concept'::public.curated_course_node_type, 'Tangential frame acceleration', null, 2),
  ('a5e88d8d-3154-47f8-b6a8-5e450d831ef8', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a1061279-b3f3-42f1-929f-6d7424ec6950', 'concept'::public.curated_course_node_type, 'Engineering examples', null, 3),
  ('8e002c49-1d46-4ee1-b2a9-da42ffa23cbc', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '574cc5aa-228c-4e7c-8481-a15a69b74dc9', 'subtopic'::public.curated_course_node_type, 'Three-dimensional rigid-body kinematics', 'Students learn how angular velocity and angular acceleration behave as vectors in space.', 2),
  ('442d3d98-0987-4a77-9862-7d907f101458', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '8e002c49-1d46-4ee1-b2a9-da42ffa23cbc', 'concept'::public.curated_course_node_type, 'Vector angular velocity', null, 0),
  ('1bb71750-6523-4963-a12b-5d4b8578d089', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '8e002c49-1d46-4ee1-b2a9-da42ffa23cbc', 'concept'::public.curated_course_node_type, 'Euler angle intuition', null, 1),
  ('0e324597-9fb5-4191-aedf-25077f6bf436', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '8e002c49-1d46-4ee1-b2a9-da42ffa23cbc', 'concept'::public.curated_course_node_type, 'Spatial relative velocity', null, 2),
  ('93bcca33-da1f-4162-bdb5-fc71361b5391', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '8e002c49-1d46-4ee1-b2a9-da42ffa23cbc', 'concept'::public.curated_course_node_type, 'Spatial acceleration', null, 3),
  ('fbee5ccc-a123-46cd-9d04-b4e07868993b', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '574cc5aa-228c-4e7c-8481-a15a69b74dc9', 'subtopic'::public.curated_course_node_type, 'Three-dimensional kinetics', 'Students get an introductory view of moments and inertia in 3D.', 3),
  ('6e63bc48-af30-4beb-8531-3c937d8801de', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'fbee5ccc-a123-46cd-9d04-b4e07868993b', 'concept'::public.curated_course_node_type, 'Inertia tensor intuition', null, 0),
  ('914b1d10-c9a9-405c-8d52-7c0ad17b7825', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'fbee5ccc-a123-46cd-9d04-b4e07868993b', 'concept'::public.curated_course_node_type, 'Euler''s equations overview', null, 1),
  ('32b57146-d449-42e9-b447-956f7ce8f448', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'fbee5ccc-a123-46cd-9d04-b4e07868993b', 'concept'::public.curated_course_node_type, 'Gyroscopic effects', null, 2),
  ('7a71fa9b-5df9-4f04-b2c8-df3d78a9df83', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'fbee5ccc-a123-46cd-9d04-b4e07868993b', 'concept'::public.curated_course_node_type, 'Aerospace and rotor applications', null, 3),
  ('5db7e24a-ae11-420b-b09b-75be8d9cbca9', '36130f37-fb21-47d4-a003-684ae5a8ed5b', null, 'topic'::public.curated_course_node_type, 'Mechanical Vibrations and Introductory System Dynamics', 'The final unit introduces dynamic response over time. Students learn how mass, stiffness, damping, and forcing create oscillatory behavior in machines and structures.', 11),
  ('a7297407-cf9a-40f9-99ca-c7c759919b79', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5db7e24a-ae11-420b-b09b-75be8d9cbca9', 'subtopic'::public.curated_course_node_type, 'Single-degree-of-freedom models', 'Students learn the simplest model for vibration analysis. The gist is to reduce a physical system to mass, spring, and damper elements.', 0),
  ('8980a0b3-a3a0-4608-b23f-09b86ec9a413', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a7297407-cf9a-40f9-99ca-c7c759919b79', 'concept'::public.curated_course_node_type, 'Mass-spring-damper model', null, 0),
  ('3cb0c03f-f991-4445-a1f1-48a7777f4876', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a7297407-cf9a-40f9-99ca-c7c759919b79', 'concept'::public.curated_course_node_type, 'Equation of motion', null, 1),
  ('8975abcc-168b-4df2-a4ee-8bbc6e4eed14', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a7297407-cf9a-40f9-99ca-c7c759919b79', 'concept'::public.curated_course_node_type, 'Natural frequency', null, 2),
  ('cc43bd84-df60-4085-80cb-3a80ef638aca', '36130f37-fb21-47d4-a003-684ae5a8ed5b', 'a7297407-cf9a-40f9-99ca-c7c759919b79', 'concept'::public.curated_course_node_type, 'Initial conditions', null, 3),
  ('0829c9fe-b233-42d8-a235-53c460d36f20', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5db7e24a-ae11-420b-b09b-75be8d9cbca9', 'subtopic'::public.curated_course_node_type, 'Free vibration and damping', 'Students learn how systems oscillate after an initial disturbance.', 1),
  ('4976e563-2a8b-4803-bef0-3276d776af2d', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0829c9fe-b233-42d8-a235-53c460d36f20', 'concept'::public.curated_course_node_type, 'Undamped response', null, 0),
  ('3e7ad0bf-1117-4154-bcfa-6c6bf4b35027', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0829c9fe-b233-42d8-a235-53c460d36f20', 'concept'::public.curated_course_node_type, 'Viscous damping', null, 1);
