  ('07f48514-a627-4df3-b311-f08bcae1b61d', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '0829c9fe-b233-42d8-a235-53c460d36f20', 'concept'::public.curated_course_node_type, 'Underdamped, critically damped, and overdamped cases', null, 3),
  ('041f07dd-3c3b-4c31-ba24-d6eb71384ef5', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5db7e24a-ae11-420b-b09b-75be8d9cbca9', 'subtopic'::public.curated_course_node_type, 'Forced vibration', 'Students learn how systems respond to external harmonic input. This explains resonance and many engineering design constraints.', 2),
