  ('fe04363e-01c6-4b70-8a9e-05383dd29161', '36130f37-fb21-47d4-a003-684ae5a8ed5b', '5db7e24a-ae11-420b-b09b-75be8d9cbca9', 'subtopic'::public.curated_course_node_type, 'Introductory modal and experimental ideas', 'Students see the bridge to graduate Dynamics and Vibrations.', 3),
