insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Engineering Mechanics: Dynamics (Hibbeler)', 'Pearson', 'R. C. Hibbeler. Highly structured undergraduate treatment with abundant particle and rigid-body examples and graded problem sets.', 0),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Engineering Mechanics: Dynamics (Meriam, Kraige, and Bolton)', 'Wiley', 'Rigorous vector mechanics, strong diagrams, and broad engineering applications. Used in current Georgia Tech syllabi.', 1),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Vector Mechanics for Engineers: Dynamics', 'McGraw Hill', 'Beer, Johnston, Cornwell, and Self. Systematic vector approach with strong coverage of kinematics, kinetics, energy, momentum, and rigid bodies.', 2),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Introduction to Statics and Dynamics', 'https://ruina.tam.cornell.edu/Book/', 'Ruina and Pratap. Free, conceptually careful mechanics reference with modeling insight and challenging problems.', 3),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Advanced Engineering Dynamics', 'Cambridge University Press', 'Jerry Ginsberg. Instructor enrichment for spatial motion, analytical mechanics, and later dynamics courses.', 4),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'textbook'::public.curated_course_resource_kind, 'Mechanical Vibrations / Engineering Vibration', 'Pearson', 'Rao and Inman. Deeper SDOF, MDOF, modal, isolation, and vibration-design treatment beyond the final course unit.', 5),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'MIT OCW 2.003SC Engineering Dynamics', 'https://ocw.mit.edu/courses/2-003sc-engineering-dynamics-fall-2011/', 'Lectures, demonstrations, problem sets, videos, and a benchmark sequence spanning rigid-body dynamics and vibration.', 6),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'MIT OCW 2.003J Dynamics and Control I', 'https://ocw.mit.edu/courses/2-003j-dynamics-and-control-i-spring-2007/', 'Computational and analytical extension through Lagrange equations, stability, and multi-degree vibration.', 7),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'Mechanics Map', 'https://mechanicsmap.psu.edu/', 'Visual explanations and worked engineering mechanics examples.', 8),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'Engineering LibreTexts - Dynamics', 'https://eng.libretexts.org/', 'Accessible chapters and examples for review and alternative explanations.', 9),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'MATLAB and Simulink', 'https://www.mathworks.com/academia/student_version.html', 'Numerical ODE solutions, parameter sweeps, animation, signal analysis, and vibration response.', 10),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'Python: NumPy, SciPy, SymPy, Matplotlib', 'https://scipy.org/', 'Reproducible numerical integration, symbolic checks, plotting, and parameter studies without license cost.', 11),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'youtube'::public.curated_course_resource_kind, 'Jeff Hanson', 'https://www.youtube.com/@1234jhanson', 'Clear worked examples in statics, dynamics, mechanics of materials, and vibrations.', 12),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'ASME Dynamic Systems and Control Division', 'https://www.asme.org/get-involved/technical-divisions/dynamic-systems-and-control-division', 'Professional bridge to dynamics, controls, mechatronics, vibration, and system design.', 13),
  ('36130f37-fb21-47d4-a003-684ae5a8ed5b', 'website'::public.curated_course_resource_kind, 'NASA Technical Reports Server and ASCE Structural Engineering Institute', 'https://ntrs.nasa.gov/', 'Instructor-selected applications in flight, rotating systems, structural dynamics, infrastructure, and hazard response. Also https://www.asce.org/communities/institutes-and-technical-groups/structural-engineering-institute.', 14);
